#!/usr/bin/env python3
"""Generate funded graph-rule experiment selection and outcome revision."""
from __future__ import annotations
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'seeds'/'experiment_design.json';AREA='experiment_design'
def V(n):return {'type':'Var','name':n}
def L(x):return {'type':'Lit','value':x}
def T(x):return {'__term__':x}
def A(n,k):return {'type':'Attr','node':V(n),'key':k}
def N(n,e):return {'type':'Neighbours','node':V(n),'edge_type':e,'any_type':False}
def Eq(a,b):return {'type':'Eq','a':a,'b':b}
def Not(x):return {'type':'Not','arg':x}
def And(*xs):return {'type':'And','items':list(xs)}
def Or(*xs):return {'type':'Or','items':list(xs)}
def Lt(a,b):return {'type':'Lt','a':a,'b':b}
def Plus(*xs):return {'type':'Plus','items':list(xs)}
def Exists(src,var,pred):return {'type':'Exists','source':src,'var_name':var,'predicate':pred}
def Count(src):return {'type':'Count','source':src}
def Concat(*xs):return {'type':'StringConcat','parts':list(xs)}
def build_seed():
 rel=[('Agent','has_experiment_design_policy','ExperimentDesignPolicy'),('Agent','has_experiment_probe','ExperimentProbe'),('ExperimentProbe','has_probe_prediction','ProbePrediction'),('ProbePrediction','based_on_hypothesis','ProcessInductionHypothesis'),('Agent','has_thinking_budget_request','ThinkingBudgetRequest'),('ThinkingBudgetRequest','funds_experiment_probe','ExperimentProbe'),('Agent','has_selected_experiment','SelectedExperiment'),('SelectedExperiment','selects_experiment_probe','ExperimentProbe'),('SelectedExperiment','based_on_probe_prediction','ProbePrediction'),('Agent','has_experiment_result','ObservedExperimentResult'),('ObservedExperimentResult','result_for_experiment','SelectedExperiment'),('Agent','has_experiment_revision_audit','ExperimentRevisionAudit'),('ExperimentRevisionAudit','audits_experiment_result','ObservedExperimentResult'),('Agent','has_world_model_projection','WorldModelProjection'),('Agent','has_process_induction_hypothesis','ProcessInductionHypothesis'),('ProcessInductionHypothesis','has_counterexample','ProcessCounterexample'),('ProcessCounterexample','counterexample_transition','TransitionObservation')]
 match=[['ag','has_experiment_design_policy','pol'],['ag','has_thinking_budget','budget'],['ag','has_network_mode_state','mode'],['ag','has_experiment_probe','probe'],['probe','has_probe_prediction','p1'],['probe','has_probe_prediction','p2']]
 distinguishing=And(Eq(A('pol','enabled'),L(1.0)),Eq(A('budget','enabled'),L(1.0)),Eq(A('probe','status'),L('proposed')),Eq(A('probe','owner_id'),A('p1','owner_id')),Eq(A('probe','owner_id'),A('p2','owner_id')),Eq(A('probe','model_epoch'),A('p1','model_epoch')),Eq(A('probe','model_epoch'),A('p2','model_epoch')),Lt(A('p1','hypothesis_key'),A('p2','hypothesis_key')),Not(Eq(A('p1','predicted_outcome'),A('p2','predicted_outcome'))),Eq(A('probe','host_veto'),L(False)),Lt(Count(N('ag','has_thinking_budget_request')),A('pol','max_requests')))
 prior=Exists(N('ag','has_thinking_budget_request'),'old',Eq(A('old','requester_key'),Concat(L('experiment:'),A('probe','owner_id'),L(':'),A('probe','probe_id'),L(':'),A('probe','model_epoch'))))
 rules=[{'name':'ed_fund_distinguishing_probe','area':AREA,'order':1,'latency_class':'hard_realtime','batch':False,'match':match,'where':And(distinguishing,Not(prior)),'effects':[['add_node','req','ThinkingBudgetRequest',{'requester_kind':'experiment_design','requester_key':T(Concat(L('experiment:'),A('probe','owner_id'),L(':'),A('probe','probe_id'),L(':'),A('probe','model_epoch'))),'source_key':T(A('probe','probe_id')),'source_epoch':T(A('probe','source_epoch')),'requested_epoch':T(A('mode','epoch')),'deadline_epoch':T(Plus(A('mode','epoch'),L(1.0))),'cost':T(A('probe','cost')),'status':'pending'}],['add_edge','ag','has_thinking_budget_request','req',{}],['add_edge','req','draws_on_thinking_budget','budget',{}],['add_edge','req','funds_experiment_probe','probe',{}]]}]
 # Choose the cheapest distinguishing, non-vetoed probe after its unique funding request is approved.
 cheaper=Exists(N('ag','has_experiment_probe'),'other',And(Eq(A('other','status'),L('proposed')),Eq(A('other','owner_id'),A('probe','owner_id')),Eq(A('other','model_epoch'),A('probe','model_epoch')),Eq(A('other','host_veto'),L(False)),Lt(A('other','cost'),A('probe','cost')),Exists(N('other','has_probe_prediction'),'op1',Exists(N('other','has_probe_prediction'),'op2',And(Not(Eq(A('op1','hypothesis_key'),A('op2','hypothesis_key'))),Not(Eq(A('op1','predicted_outcome'),A('op2','predicted_outcome'))))))))
 rules.append({'name':'ed_select_minimum_cost_distinguishing_probe','area':AREA,'order':2,'latency_class':'background','batch':False,'match':[['ag','has_experiment_design_policy','pol'],['ag','has_experiment_probe','probe'],['probe','has_probe_prediction','p1'],['probe','has_probe_prediction','p2'],['req','funds_experiment_probe','probe']],'where':And(Eq(A('pol','enabled'),L(1.0)),Eq(A('probe','status'),L('proposed')),Eq(A('req','status'),L('approved')),Eq(A('probe','host_veto'),L(False)),Lt(A('p1','hypothesis_key'),A('p2','hypothesis_key')),Not(Eq(A('p1','predicted_outcome'),A('p2','predicted_outcome'))),Not(Exists(N('ag','has_selected_experiment'),'old',Eq(A('old','probe_id'),A('probe','probe_id'))))),'effects':[['add_node','sel','SelectedExperiment',{'selection_id':T(Concat(L('selected:'),A('probe','probe_id'))),'probe_id':T(A('probe','probe_id')),'owner_id':T(A('probe','owner_id')),'model_epoch':T(A('probe','model_epoch')),'status':'selected','information_status':'hypotheses_separated','voi_claim':'qualitative_only'}],['add_edge','ag','has_selected_experiment','sel',{}],['add_edge','sel','selects_experiment_probe','probe',{}],['add_edge','sel','based_on_probe_prediction','p1',{}],['add_edge','sel','based_on_probe_prediction','p2',{}],['set_attr','probe','status','selected']]})
 rules.append({'name':'ed_supersede_more_expensive_selection','area':AREA,'order':3,'latency_class':'background','batch':False,'match':[['ag','has_selected_experiment','s1'],['ag','has_selected_experiment','s2'],['s1','selects_experiment_probe','p1'],['s2','selects_experiment_probe','p2']],'where':And(Eq(A('s1','status'),L('selected')),Eq(A('s2','status'),L('selected')),Eq(A('s1','owner_id'),A('s2','owner_id')),Eq(A('s1','model_epoch'),A('s2','model_epoch')),Not(Eq(A('s1','selection_id'),A('s2','selection_id'))),Or(Lt(A('p1','cost'),A('p2','cost')),And(Eq(A('p1','cost'),A('p2','cost')),Lt(A('p1','probe_id'),A('p2','probe_id'))))),'effects':[['set_attr','s2','status','superseded'],['set_attr','p2','status','superseded']]})

 def assessment_rule(supporting):
  assessment='supports' if supporting else 'disconfirms'
  outcome_cond=Eq(A('prediction','predicted_outcome'),A('result','observed_outcome')) if supporting else Not(Eq(A('prediction','predicted_outcome'),A('result','observed_outcome')))
  duplicate=Exists(N('ag','has_experiment_revision_audit'),'old',And(Eq(A('old','result_id'),A('result','result_id')),Eq(A('old','hypothesis_key'),A('prediction','hypothesis_key'))))
  effects=[['add_node','audit','ExperimentRevisionAudit',{'result_id':T(A('result','result_id')),'probe_id':T(A('probe','probe_id')),'hypothesis_key':T(A('prediction','hypothesis_key')),'observed_outcome':T(A('result','observed_outcome')),'expected_outcome':T(A('prediction','predicted_outcome')),'model_epoch':T(A('result','model_epoch')),'status':assessment}],['add_edge','ag','has_experiment_revision_audit','audit',{}],['add_edge','audit','audits_experiment_result','result',{}],['set_attr','prediction','result_status',assessment]]
  if supporting:
   effects.append(['set_attr','hyp','last_experiment_evidence','supporting'])
  else:
   effects.extend([['add_node','ce','ProcessCounterexample',{'event_id':T(A('result','result_id')),'observed_after_value':T(A('result','observed_outcome')),'status':'observed'}],['add_edge','hyp','has_counterexample','ce',{}],['set_attr','hyp','status','disputed'],['set_attr','hyp','counterexample_count',T(Plus(A('hyp','counterexample_count'),L(1.0)))]] )
  rules.append({'name':'ed_'+assessment+'_hypothesis_from_observed_outcome','area':AREA,'order':10,'latency_class':'background','batch':False,'match':[['ag','has_experiment_design_policy','pol'],['ag','has_selected_experiment','sel'],['sel','selects_experiment_probe','probe'],['sel','based_on_probe_prediction','prediction'],['prediction','based_on_hypothesis','hyp'],['ag','has_experiment_result','result'],['result','result_for_experiment','sel']], 'where':And(Eq(A('pol','enabled'),L(1.0)),Or(Eq(A('sel','status'),L('selected')),Eq(A('sel','status'),L('completed'))),Eq(A('result','status'),L('observed')),Eq(A('result','owner_id'),A('sel','owner_id')),Eq(A('result','model_epoch'),A('sel','model_epoch')),Eq(A('result','probe_id'),A('sel','probe_id')),Eq(A('hyp','hypothesis_key'),A('prediction','hypothesis_key')),outcome_cond,Not(duplicate)),'effects':effects})
 assessment_rule(True);assessment_rule(False)
 rules.append({'name':'ed_recompute_portfolio_projection_after_observed_result','area':AREA,'order':11,'latency_class':'background','batch':False,'match':[['ag','has_experiment_design_policy','pol'],['ag','has_selected_experiment','sel'],['sel','selects_experiment_probe','probe'],['ag','has_experiment_result','result'],['result','result_for_experiment','sel'],['ag','has_world_model_projection','projection']],'where':And(Eq(A('pol','enabled'),L(1.0)),Eq(A('result','status'),L('observed')),Eq(A('result','owner_id'),A('sel','owner_id')),Eq(A('result','model_epoch'),A('sel','model_epoch')),Eq(A('result','probe_id'),A('sel','probe_id')),Eq(A('projection','owner_id'),A('sel','owner_id')),Eq(A('projection','model_epoch'),A('sel','model_epoch')),Not(Exists(N('ag','has_experiment_revision_audit'),'old',And(Eq(A('old','result_id'),A('result','result_id')),Eq(A('old','status'),L('projection_recomputed')))))),'effects':[['add_node','audit','ExperimentRevisionAudit',{'result_id':T(A('result','result_id')),'probe_id':T(A('probe','probe_id')),'hypothesis_key':'portfolio_projection','observed_outcome':T(A('result','observed_outcome')),'model_epoch':T(A('result','model_epoch')),'status':'projection_recomputed'}],['add_edge','ag','has_experiment_revision_audit','audit',{}],['add_edge','audit','audits_experiment_result','result',{}],['set_attr','projection','version',T(Plus(A('projection','version'),L(1.0)))],['set_attr','projection','last_result_id',T(A('result','result_id'))],['set_attr','projection','revision_status','recomputed'],['set_attr','sel','status','completed'],['set_attr','probe','status','completed']]})

 return {'id':'experiment_design','version':'1.0.0','depends_on':['process_induction','thinking_budget','cognition_manifold'],'self_load_only':True,'area':AREA,'description':'P8.04: fund and select a host-authorized discriminating probe, then update hypothesis and projection audit from its observed outcome.','microtheory':{'name':AREA,'description':'Choose bounded experiments from distinct predicted outcomes; unknown priors do not become numeric VOI.'},'nodes':[{'local_id':0,'type':'ExperimentDesignPolicy','attrs':{'name':'experiment_design_policy','enabled':0.0,'max_requests':32.0,'max_candidates':32.0,'max_event_refs':200.0}}],'edges':[{'src':{'role':'agent_root'},'type':'has_experiment_design_policy','tgt':{'local':0},'attrs':{}}],'productions':[{'provenance':f'seed:{AREA}:{e}:{s}:{t}','src':{'type':s,'var':'src'},'edge_type':e,'tgt':{'type':t,'var':'tgt'}} for s,e,t in rel],'rules':rules}
if __name__=='__main__':OUT.write_text(json.dumps(build_seed(),indent=2,ensure_ascii=False)+'\n',encoding='utf-8');print(OUT)
